// Generated by philote from page /horses. Do not edit.
import type { Metadata } from "next";
import { connection } from "next/server";
import { Suspense } from "react";

import { horses } from "@/lib/api";
import { must } from "@/lib/backend";
import { readHorseCard } from "@/lib/reads";

import HorseCard from "@/components/common/horse-card";

export const metadata: Metadata = { title: "Horses" };

export default function Page() {
    return (
        <main className="flex-1 p-8">
            <div className="mx-auto max-w-4xl space-y-6">
                <h1 className="font-heading text-4xl">{"Horses"}</h1>
                <Suspense fallback={<p className="text-muted-foreground">Loading…</p>}>
                    <Records />
                </Suspense>
            </div>
        </main>
    );
}

async function Records() {
    await connection();
    const records = await must(horses.list());
    if (records.length === 0) {
        return <p className="text-muted-foreground">{"No horses yet."}</p>;
    }
    const items = await Promise.all(records.map(readHorseCard));
    return (
        <div className="grid gap-4 md:grid-cols-2">
            {items.map((item) => (
                <HorseCard key={item.horse.id} {...item} />
            ))}
        </div>
    );
}
